	if err != nil {
		t.Fatal(err)
	}
	if result.OutcomeCounts[QATheoryConfirmed] != 1 || result.OutcomeCounts[QATheoryRefuted] != 1 || result.OutcomeCounts[QATheoryCrossShard] != 1 || result.OutcomeCounts[QATheoryInconclusive] != 1 {
