	"testing"
	"time"
)

// Mirrors RunQA's frozen sequence: synthesis -> run proposed follow-ups ->
// re-synthesize -> hydrate. A follow-up investigator may lawfully return an
// inconclusive or cross_shard theory (prompt permits it; ValidateQATheory
// accepts it). The second synthesis then proposes a NEW follow-up shard ID
// derived from that theory, which was never retained or executed.
func TestReproFollowUpRoundTwoWedgesAttempt(t *testing.T) {
	qaMap, shards := qaSynthesisFixture(t)
	s1, err := SynthesizeQA(qaMap, shards)
	if err != nil {
		t.Fatal(err)
	}
	if len(s1.FollowUpShards) == 0 {
		t.Fatal("expected round-1 follow-ups")
	}
	executed := append([]QAShard(nil), shards...)
	now := time.Now().UTC()
	for _, follow := range s1.FollowUpShards {
		follow.Phase = QAPhaseCompleted
		identity := QATheoryIdentity{Claim: "follow-up remains unclear", Basis: "deeper look", VerificationSurface: "public behavior", ExpectationRefs: []string{"REQ-1"}}
		id, idErr := NewQATheoryID(qaMap.Project, qaMap.Sprint, follow.ID, identity)
		if idErr != nil {
			t.Fatal(idErr)
		}
		theory := QATheory{SchemaVersion: QASchemaVersion, ID: id, ShardID: follow.ID, Claim: identity.Claim, Basis: identity.Basis, VerificationSurface: identity.VerificationSurface, ExpectationRefs: identity.ExpectationRefs, SeverityIfConfirmed: "medium", ConfirmationCondition: "c", RefutationCondition: "r", InconclusiveCondition: "i", SafeEvidenceStrategy: "s", ImplementationFingerprint: qaMap.ImplementationFingerprint, AttemptHistory: []QAInvestigatorAttempt{{ID: "op/f/1", Number: 1, StartedAt: now}}, Outcome: QATheoryInconclusive, OutcomeReason: "still unclear"}
		if err := ValidateQATheory(theory); err != nil {
			t.Fatal(err)
		}
		follow.Theories = []QATheory{theory}
		executed = append(executed, follow)
	}
	s2, err := SynthesizeQA(qaMap, executed)
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("round-2 proposed %d follow-up shards", len(s2.FollowUpShards))
	known := map[string]bool{}
	for _, shard := range executed {
		known[shard.ID] = true
	}
	novel := 0
	for _, follow := range s2.FollowUpShards {
		if !known[follow.ID] {
			novel++
		}
	}
	t.Logf("novel unexecuted follow-up IDs proposed by deterministic synthesis: %d", novel)
	if err := hydrateQASynthesisFollowUps(&s2, executed); err == nil {
		t.Fatalf("expected RunQA wedge: hydration accepted %d proposals with %d novel IDs", len(s2.FollowUpShards), novel)
	}
}
EOF
