package sprint

import (
	"path/filepath"
	"testing"
	"time"
)

// Frozen RunQA has no all-shards-terminal gate between runQAShardBatch and
// state.Phase=Completed. A focused batch returns nil while every other shard
// stays mapped, and SynthesizeQA tolerates pending shards.
func TestReproFocusedBatchLeavesShardsPendingAndSynthesisAccepts(t *testing.T) {
	root, sp, target, qaMap, flow, state, token := qaRunFixture(t)
	service := NewService(root).WithRuntime(&qaInvestigatorRuntime{}).WithQASettings(QASettings{Runtime: StageRuntime{Model: "openai/qa"}, Budgets: qaMap.Budgets}).WithQAMapFence(func(QAMap) error { return nil })
	store := NewQAStore(root, sp).WithWriterFence(func(QAWriterToken) error { return nil })
	if len(qaMap.Shards) < 2 {
		t.Fatal("fixture needs multiple shards")
	}
	shards, _, err := service.runQAShardBatch(t.Context(), store, flow, qaMap, target, append([]QAShard(nil), qaMap.Shards...), state, QARunRequest{WriterToken: token, FocusShard: qaMap.Shards[0].ID})
	if err != nil {
		t.Fatal(err)
	}
	pending := 0
	for _, shard := range shards {
		if shard.Phase == QAPhaseMapped {
			pending++
		}
	}
	t.Logf("after focused batch: pending(mapped)=%d of %d", pending, len(shards))
	if pending == 0 {
		t.Fatal("expected pending shards after focused batch")
	}
	if _, err := SynthesizeQA(qaMap, shards); err != nil {
		t.Fatalf("synthesis rejected partially investigated attempt: %v", err)
	}
}

// prepareQAAttempt's resume branch rebuilds the shard list from the map's
// planned shards only. Follow-up shards persisted by an interrupted run are
// never merged back, so the regenerated follow-ups re-run from scratch.
func TestReproResumeDropsPersistedFollowUpProgress(t *testing.T) {
	root, sp, _, qaMap, flow, state, token := qaRunFixture(t)
	store := NewQAStore(root, sp).WithWriterFence(func(QAWriterToken) error { return nil })
	service := NewService(root).WithQASettings(QASettings{Runtime: StageRuntime{Model: "openai/qa"}, Budgets: qaMap.Budgets})
	if err := store.Publish(QAPublication{Map: &qaMap, Shards: qaMap.Shards, State: state, Flow: flow}, token); err != nil {
		t.Fatal(err)
	}
	// Persist one completed follow-up shard owned by the current attempt,
	// exactly as RunQA's mid-run publication would.
	follow := QAShard{SchemaVersion: QASchemaVersion, ID: qaFollowUpIDForTest(t, qaMap), AttemptID: qaMap.SemanticAttemptID, Kind: QAShardFollowUp, Title: "Follow up x", ContextPaths: []string{"internal/app/usecases.go"}, BehavioralConcerns: []string{"follow up: x"}, ExpectationRefs: []string{"REQ-WEB"}, ParentTheoryIDs: []string{"qa-v1-theory-" + filepath.Base("aaaaaaaaaaaaaaaaaaaaaaaa")}, Phase: QAPhaseCompleted}
	if !validQAID(follow.ID) {
		t.Fatalf("bad fixture follow-up id %q", follow.ID)
	}
	if err := store.Publish(QAPublication{Shards: []QAShard{follow}, State: state, Flow: flow}, token); err != nil {
		t.Fatal(err)
	}
	if _, err := store.LoadShard(qaMap.SemanticAttemptID, follow.ID); err != nil {
		t.Fatalf("follow-up was not retained: %v", err)
	}
	state.TotalShards = len(qaMap.Shards) + 1
	state.UpdatedAt = time.Now().UTC()
	resumed, shards, err := service.prepareQAAttempt(store, flow, qaMap, QARunRequest{Resume: true, WriterToken: token}, QASettings{Runtime: StageRuntime{Model: "openai/qa"}, Budgets: qaMap.Budgets})
	if err != nil {
		t.Fatal(err)
	}
	hasFollow := false
	for _, shard := range shards {
		if shard.ID == follow.ID {
			hasFollow = true
		}
	}
	t.Logf("resumed TotalShards=%d shards=%d retained-follow-up-merged=%v", resumed.TotalShards, len(shards), hasFollow)
	if hasFollow {
		t.Fatal("resume merged the retained follow-up")
	}
	if resumed.TotalShards != len(qaMap.Shards) {
		t.Fatalf("resume reset TotalShards to %d", resumed.TotalShards)
	}
}

func qaFollowUpIDForTest(t *testing.T, qaMap QAMap) string {
	t.Helper()
	identity := QAShardIdentity{Kind: QAShardFollowUp, ContextPaths: []string{"internal/app/usecases.go"}, BehavioralConcerns: []string{"follow up: x"}, ExpectationRefs: []string{"REQ-WEB"}, ParentTheoryIDs: []string{"parent"}}
	id, err := NewQAShardID(qaMap.Project, qaMap.Sprint, qaMap.ID, identity)
	if err != nil {
		t.Fatal(err)
	}
	return id
}
EOF
