package sprint

import (
	"strings"
	"testing"
	"time"
)

// Independent probe of evidence-publication replay: same semantic content,
// two freeze instants. Plan IDs exclude FrozenAt; persisted bytes include it.
func TestReproEvidencePlanReplayConflicts(t *testing.T) {
	budgets := DefaultQABudgets()
	mk := func(now time.Time) QAEvidencePlan {
		plan, err := FreezeQAEvidencePlan("alpha", "01-test", QAEvidencePlan{
			AttemptID: "qa-v1-attempt-" + strings.Repeat("a", 24), ShardID: "qa-v1-shard-" + strings.Repeat("b", 24),
			Kind: QACheckFact, ConfirmationCondition: "pass", RefutationCondition: "fail", InconclusiveCondition: "unclear",
			ApprovedPaths: []string{"internal/app/usecases.go"}, Executable: "/usr/bin/gofmt", Args: []string{"-d", "internal/app/usecases.go"},
			Timeout: budgets.CommandTimeout, OutputLimit: budgets.CommandOutputBytes,
			GovernedInputFingerprint: strings.Repeat("1", 64), ImplementationFingerprint: strings.Repeat("2", 64), MapFingerprint: strings.Repeat("3", 64),
		}, budgets, now)
		if err != nil {
			t.Fatal(err)
		}
		return plan
	}
	p1 := mk(time.Unix(1000, 0).UTC())
	p2 := mk(time.Unix(2000, 0).UTC())
	t.Logf("same plan id across freeze instants: %v (%s)", p1.ID == p2.ID, p1.ID)
	if p1.ID != p2.ID {
		t.Fatal("expected deterministic plan id")
	}
	if p1.FrozenAt.Equal(p2.FrozenAt) {
		t.Fatal("expected differing frozen timestamps")
	}
	root := t.TempDir()
	sp := Sprint{Project: "alpha", Slug: "01-test", Path: root}
	store := NewQAStore(root, sp).WithWriterFence(func(QAWriterToken) error { return nil })
	path, err := store.resolve(QAEvidencePlanRelPath(sp, p1.AttemptID, p1.ID))
	if err != nil {
		t.Fatal(err)
	}
	if _, err := store.writeRecord("evidence-plan", path, &p1, true); err != nil {
		t.Fatalf("first publish failed: %v", err)
	}
	_, err = store.writeRecord("evidence-plan", path, &p2, true)
	t.Logf("second publish error: %v", err)
	typed, ok := AsQAError(err)
	if !ok || typed.Category != QAErrorConflict {
		t.Fatalf("expected conflict, got %v", err)
	}
}
EOF
